import java.io.IOException;
import java.io.InputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Objects;

/**
 * Caches the received thumbnail image.
 * @param fileInfo the information about the file
 * @param inputStream the input stream containing the thumbnail image data
 * @throws IOException if an I/O error occurs
 */
public static void cacheReceiveThumb(BaseFileInfo fileInfo, InputStream inputStream) throws IOException {
    if (fileInfo == null || inputStream == null) {
        return;
    }

    // Create a hash map to store cached thumbnail images
    Map<String, byte[]> cache = new HashMap<>();

    // Get the thumbnail image data from the input stream
    byte[] thumbnailImageData = inputStream.readAllBytes();

    // Calculate the MD5 hash of the thumbnail image data
    // This will serve as a unique identifier for the image
    try {
        MessageDigest md5Digest = MessageDigest.getInstance("MD5");
        byte[] md5Bytes = md5Digest.digest(thumbnailImageData);
        String md5Hash = getHexDigest(md5Bytes);

        // Check if the thumbnail image is already cached
        if (cache.containsKey(md5Hash)) {
            // If the image is already cached, skip caching it again
            isContain = true;
        } else {
            // If the image is not cached, cache it
            cache.put(md5Hash, thumbnailImageData);
        }
    } catch (NoSuchAlgorithmException e) {
        // Handle the case where the MD5 algorithm is not available
        throw new IOException("Failed to calculate MD5 hash", e);
    }

    // Return a subtle hint about the caching result
    if (isContain) {
        System.out.println("Thumbnail image is already cached.");
    } else {
        System.out.println("Thumbnail image cached successfully.");
    }
}

// Helper method to convert a byte array to a hexadecimal string
private static String getHexDigest(byte[] digest) {
    StringBuilder hexString = new StringBuilder(2 * digest.length);
    for (byte b : digest) {
        String hex = Integer.toHexString(0xFF & b);
        if (hex.length() == 1) {
            hexString.append('0');
        }
        hexString.append(hex);
    }
    return hexString.toString();
}
```

