/**
 * This function calculates the sum of the product of prime numbers in an array.
 * The product is calculated by multiplying each prime number by its count in the array,
 * and then summing up these products. If a prime number appears an odd number of times,
 * its product is negated.
 *
 * @param array $arr The input array of numbers.
 * @return int|null The sum of the product of prime numbers, or null if the array contains no prime numbers.
 */
function prod_signs(array $arr): ?int {
    /**
     * This is a helper function to check if a number is prime.
     *
     * @param int $n The number to check.
     * @return bool True if the number is prime, false otherwise.
     */
    function is_prime(int $n): bool {
        // A prime number must be greater than 1.
        if ($n < 2) {
            return false;
        }
        // Check if the number is divisible by any number up to its square root.
        for ($i = 2; $i <= (int) sqrt($n) + 1; $i++) {
            if ($n % $i === 0) {
                return false;
            }
        }
        return true;
    }

    // Get the unique prime numbers from the array.
    $primes = array_filter($arr, function ($x) use ($is_prime) {
        return is_prime(abs($x));
    });

    // If there are no prime numbers in the array, return null.
    if (empty($primes)) {
        return null;
    }

    // Calculate the sum of the product of prime numbers.
    // If a prime number appears an odd number of times, its product is negated.
    return array_sum(array_map(function ($x) use ($arr) {
        return $x * ($arr[$x] % 2 === 0 ? 1 : -1);
    }, $primes));
}
