CREATE FUNCTION is_fibonacci(num INTEGER) RETURNS BOOLEAN AS $$
DECLARE
    a INTEGER := 0;
    b INTEGER := 1;
    c INTEGER := 1;
BEGIN
    IF num < 0 THEN
        RETURN FALSE;
    END IF;
    WHILE c < num LOOP
        a := b;
        b := c;
        c := a + b;
    END LOOP;
    RETURN c = num;
END;
